import json, pathlib, platform, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def build_project(name, source, strict=False):
    root = write_project(name, source)
    cmd = [str(fz), 'build', str(root), '--json']
    if strict:
        cmd.append('--strict')
    proc = subprocess.run(cmd, cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    return root, proc.returncode, payload

def verify_project(name, source, strict=False):
    root = write_project(name, source)
    cmd = [str(fz), 'verify', str(root), '--json']
    if strict:
        cmd.append('--strict')
    proc = subprocess.run(cmd, cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    return root, proc.returncode, payload

def find(items, needle):
    return next(item for item in items if needle in item['message'])

artifact_root, artifact_rc, artifact_payload = build_project('gpu_event_async_policy_artifacts', '''
    use core.gpu;
    use core.thread;
    kernel fn copy(input: GpuSlice<f32>, output: GpuSlice<f32>, n: i32) -> void {
        let i = gpu.global_id_x();
        if i < n {
            output[i] = input[i];
        }
    }
    async host fn flush(event: GpuEvent) -> void {
        await gpu.wait_async(event)
    }
    async host fn main() -> i32 {
        let dev = gpu.default_device();
        let input = gpu.alloc_f32(dev, 4);
        defer gpu.free(input);
        let output = gpu.alloc_f32(dev, 4);
        defer gpu.free(output);
        let event = gpu.launch3(copy, 1, 64, gpu.slice(input, 0, 4), gpu.slice(output, 0, 4), 4);
        timeout(25)
        await flush(event)
        return 0
    }
''')
assert artifact_rc == 0 and artifact_payload['status'] == 'ok', (artifact_rc, artifact_payload)
async_report = json.loads((artifact_root / '.fz' / 'async-safety.json').read_text())
assert async_report['strictRequirements']['gpuEventTerminalPolicy'] is True, async_report
assert async_report['cancellationModel']['gpuEventCancellation'] == 'deadline_bound_wait_then_cleanup', async_report
assert 'gpu.wait_async' in async_report['stateMachine']['gpuEventTerminalOperations'], async_report
assert any(item['callee'] == 'gpu.wait_async' and item['bounded'] is True and item['bounding'] == 'task_local_timeout_or_deadline' for item in async_report['runtime_wait_policies']), async_report['runtime_wait_policies']
assert any(item['event'] == 'event' and item['currentState'] == 'waited' and item['waitBounded'] is True for item in async_report['gpu_event_policies']), async_report['gpu_event_policies']

strict_root, strict_rc, strict_payload = verify_project('gpu_event_async_policy_strict', '''
    use core.gpu;
    use core.thread;
    kernel fn copy(input: GpuSlice<f32>, output: GpuSlice<f32>, n: i32) -> void {
        let i = gpu.global_id_x();
        if i < n {
            output[i] = input[i];
        }
    }
    async host fn main() -> i32 {
        let dev = gpu.default_device();
        let input = gpu.alloc_f32(dev, 4);
        defer gpu.free(input);
        let output = gpu.alloc_f32(dev, 4);
        defer gpu.free(output);
        let event = gpu.launch3(copy, 1, 64, gpu.slice(input, 0, 4), gpu.slice(output, 0, 4), 4);
        await gpu.wait_async(event)
        return 0
    }
''', strict=True)
assert strict_rc == 1, (strict_rc, strict_payload)
diag = find(strict_payload['items'], 'function `main` performs blocking gpu_event wait `gpu.wait_async` without a timeout/deadline bound')
assert 'GPU event waits should be deadline-bound' in (diag.get('help') or ''), diag
event_diag = find(strict_payload['items'], 'gpu event `event` in `main` reaches `gpu.wait`/`gpu.wait_async` without a task-local timeout/deadline bound')
assert 'pending launch cleanup stay bounded' in (event_diag.get('help') or ''), event_diag
strict_async = json.loads((strict_root / '.fz' / 'async-safety.json').read_text())
assert any(item['event'] == 'event' and item['currentState'] == 'pending' and item['waitBounded'] is False for item in strict_async['gpu_event_policies']), strict_async['gpu_event_policies']
assert any(item['kind'] == 'gpu_event_unbounded_wait' for item in strict_async['gpu_event_findings']), strict_async['gpu_event_findings']

