if platform.system() == 'Darwin':
    run_proc = subprocess.run([str(fz), 'run', str(bounded_root), '--proc-backend', 'host', '--fs-backend', 'host', '--http-backend', 'host', '--json'], cwd=str(repo), capture_output=True, text=True)
